import { useMemo } from "react";
import { money } from "./foundationCalc";

const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const qty = (n, unit) => `${num(n).toLocaleString(undefined, { maximumFractionDigits: 2 })} ${unit}`;
const EMPTY_ITEMS = [];
const EMPTY_POLES = [];
const EMPTY_WALLS = [];
const EMPTY_TOTALS = {};
const EMPTY_INVENTORY = [];

export default function FoundationBOM({
  items = EMPTY_ITEMS,
  poles = EMPTY_POLES,
  walls = EMPTY_WALLS,
  delivery,
  totals = EMPTY_TOTALS,
  inventory = EMPTY_INVENTORY,
}) {
  const rows = useMemo(() => {
    const out = [];
    const add = (material, quantity, cost) => {
      if (num(quantity) <= 0 && num(cost) <= 0) return;
      out.push({ material, quantity, cost });
    };
    const nameOf = (id) => inventory.find((i) => i.id === id)?.material_name || "Material";

    if (num(delivery?.roundedYards) > 0) {
      add("Ready-mix concrete (delivered)", qty(delivery.roundedYards, "CY"), delivery.concreteTotal);
    }
    const bags = items.reduce((s, i) => s + num(i.concrete_bags), 0);
    const baggedCost = items.reduce((s, i) => s + num(i.concrete_cost), 0);
    if (bags > 0) add("Bagged concrete", qty(bags, "bags"), baggedCost);

    const rebarFt = items.reduce((s, i) => s + num(i.rebar_feet), 0);
    const rebarLbs = items.reduce((s, i) => s + num(i.rebar_weight_lbs), 0);
    if (rebarFt > 0) {
      add(`Rebar (${qty(rebarLbs, "lbs")})`, qty(rebarFt, "LF"), totals.total_rebar_cost);
    }

    const formingQty = items.reduce((s, i) => s + num(i.forming_qty), 0);
    if (formingQty > 0) add("Forming material", qty(formingQty, "units"), totals.total_forming_materials_cost);

    const poleGroups = {};
    poles.forEach((p) => {
      if (!p.pole_id || num(p.pole_cost) <= 0) return;
      poleGroups[p.pole_id] = poleGroups[p.pole_id] || { ft: 0, cost: 0 };
      poleGroups[p.pole_id].ft += (num(p.height_inches) + num(p.y_offset_inches)) / 12;
      poleGroups[p.pole_id].cost += num(p.pole_cost);
    });
    Object.entries(poleGroups).forEach(([id, g]) => add(nameOf(id), qty(g.ft, "LF"), g.cost));

    if (num(totals.total_pole_painting_cost) > 0) {
      add("Pole painting", "—", totals.total_pole_painting_cost);
    }

    walls.forEach((w, i) => {
      const c = w.calculatedCosts || {};
      const label = w.name || `Wall ${i + 1}`;
      if (num(c.materialCost) > 0) add(`${label} — ${nameOf(w.materialId)}`, qty(c.totalBricks, "units"), c.materialCost);
      if (num(c.mortarCost) > 0) add(`${label} — mortar`, "—", c.mortarCost);
      if (num(c.internalMaterialCost) > 0) {
        add(
          `${label} — ${nameOf(w.internalMaterialId)} (internal)`,
          qty(c.internalTotalBricks, "units"),
          c.internalMaterialCost
        );
      }
      if (num(c.internalMortarCost) > 0) add(`${label} — internal mortar`, "—", c.internalMortarCost);
    });

    (totals.wall_caps_by_material || []).forEach((g) => add(g.name || "Wall cap", qty(g.qty, "pcs"), g.cost));

    return out;
  }, [items, poles, walls, delivery, totals, inventory]);

  const materialTotal = rows.reduce((s, r) => s + num(r.cost), 0);

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4">
      <h3 className="font-semibold text-gray-900 mb-3">Bill of Materials</h3>
      {rows.length === 0 ? (
        <p className="text-sm text-gray-500">No materials yet — add a foundation to build the list.</p>
      ) : (
        <>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 border-b border-gray-200">
                <th className="py-1.5">Material</th>
                <th className="py-1.5">Quantity</th>
                <th className="py-1.5 text-right">Cost</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={i} className="border-b border-gray-100 last:border-0">
                  <td className="py-1.5 text-gray-800">{r.material}</td>
                  <td className="py-1.5 text-gray-600">{r.quantity}</td>
                  <td className="py-1.5 text-right text-gray-900">{money(r.cost)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="flex justify-between pt-3 mt-1 border-t border-gray-200 font-bold text-gray-900">
            <span>Material total</span>
            <span>{money(materialTotal)}</span>
          </div>
        </>
      )}
    </div>
  );
}

import { foundationEquipmentCatalogIssues } from "./foundationEquipmentBindings";

// Availability only: this does not validate rates, geometry, or engineering.
export function foundationAssemblyCatalogIssues(project, inventory = []) {
  const available = new Set(inventory.map((row) => row.id));
  const issues = [];
  const check = (row, index, kind, field, label) => {
    const id = row[field];
    const assigned = (typeof id === "string" && id.trim() !== "")
      || (typeof id === "number" && Number.isFinite(id));
    if (assigned && available.has(id)) return;
    issues.push({
      kind,
      index,
      componentId: row.component_id ?? row.id ?? null,
      field,
      inventoryId: assigned ? id : null,
      code: assigned ? "catalog_item_unavailable" : "catalog_item_unassigned",
      message: `${label} ${index + 1}: ${assigned ? "selected catalog material is unavailable" : "select a catalog material"}.`,
    });
  };
  for (const [index, pole] of (project?.poles || []).entries()) {
    check(pole, index, "pole", "pole_id", "Pole");
  }
  for (const [index, cap] of (project?.wall_caps || []).entries()) {
    check(cap, index, "wall_cap", "cap_inventory_id", "Wall cap");
  }
  for (const [index, wall] of (project?.walls || []).entries()) {
    check(wall, index, "wall", "materialId", "Wall");
    if (wall.includeInternalWall) {
      check(wall, index, "internal_wall", "internalMaterialId", "Internal wall");
    }
  }
  return [...issues, ...foundationEquipmentCatalogIssues(project?.selected_equipment || [], inventory)];
}

// A missing snapshot is not evidence of a free material.
export function hasFoundationCostSnapshot(value) {
  return typeof value === "number" && Number.isFinite(value);
}

// Cost engine for the Concrete | Masonry | Poles estimator.
//
// All math is ported from SignEstimate Pro and must stay identical to it:
//  - per-item concrete / rebar / forming / finishing / pouring / excavation → legacyFoundationCalc.js
//  - project concrete delivery (trucks, fees, stops)                        → legacyFoundationCalc.js
//  - masonry walls (outer + internal fill wall)                            → wallCalculator.js
//  - poles + pole painting                                                  → poleCalculator.js
//  - wall caps (full stock charged per cut piece)                           → wallCapCalculator.js
//
// Rollup (verbatim from SignEstimate Pro `totals`):
//   grand = itemsTotal(+concrete delivery) + wallTotal + polesTotal + equipmentTotal + wallCapTotal
// Poles, walls, caps and fill are PROJECT-level — they are never charged on a foundation item.

import { calcItemCost as legacyCalcItemCost, calcConcreteDelivery } from "./legacyFoundationCalc";
import { calcWalls } from "./wallCalculator";
import { calcPoles } from "./poleCalculator";
import { calcWallCaps } from "./wallCapCalculator";
import { foundationAssemblyCatalogIssues } from "./foundationCatalogIntegrity";
import { resolveFoundationEquipment } from "./foundationEquipmentBindings";

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

const REBAR_LB_PER_FT = { "#3": 0.376, "#4": 0.668, "#5": 1.043, "#6": 1.502, "#7": 2.044, "#8": 2.67 };

export function calcItem(item, project, inventory, settings = {}) {
  // Items without their own excavation method fall back to the project default.
  const legacy = legacyCalcItemCost(
    { ...item, excavation_method: item.excavation_method || project?.excavation_method },
    inventory,
    settings
  );
  const isPillar = item.foundation_type === "pillar";
  const rebarSize = (isPillar ? item.pillar_rebar_size : item.rebar_size) || "#4";

  return {
    quantity: Math.max(1, num(item.quantity, 1)),
    concrete_volume_cy: legacy.volumeCY,
    excavation_volume_cy: legacy.volumeCY * 1.25,
    concrete_bags: legacy.concreteBags,
    rebar_feet: legacy.rebarFt,
    rebar_weight_lbs: legacy.rebarFt * (REBAR_LB_PER_FT[rebarSize] || 0.668),
    concrete_cost: legacy.concreteCost,
    concrete_rate: legacy.concreteRate,
    rebar_cost: legacy.rebarCost,
    rebar_rate: legacy.rebarRate,
    excavation_cost: legacy.excavationCost,
    excavation_hours: legacy.excavationHours,
    forming_cost: legacy.formingCost,
    forming_qty: legacy.formingQty,
    pouring_cost: legacy.pouringCost,
    finishing_cost: legacy.finishingCost,
    finishing_hours: legacy.finishingHours,
    item_total_cost: legacy.total,
  };
}

// Equipment rental — ported from SignEstimate Pro `equipmentTotal`.
export function calcEquipmentPricing(selected, inventory = []) {
  return (selected || []).map((storedEntry, index) => {
    const entry = storedEntry || {};
    const bindings = resolveFoundationEquipment(entry, inventory, index);
    const eq = bindings.equipment;
    const rentalPeriod = entry.rental_period || "day";
    const durationOverride =
      entry.custom_qty !== undefined && entry.custom_qty !== null ? entry.custom_qty : entry.rental_duration || 1;
    const context = { ...bindings, rentalPeriod, duration: durationOverride };
    if (bindings.issues.length) {
      return {
        ...context, pricedEntry: { ...entry }, baseCost: null, deliveryCost: null,
        totalCost: entry.equipment_cost,
        attachmentRows: bindings.attachmentRows.map(row => ({ ...row, cost: null })),
        subAttachmentRows: bindings.subAttachmentRows.map(row => ({ ...row, cost: null })),
      };
    }

    const getRentalCost = (item, rateOverride) => {
      if (rateOverride !== undefined && rateOverride !== null) return rateOverride * durationOverride;
      if (rentalPeriod === "day") return num(item.cost_per_day) * durationOverride;
      if (rentalPeriod === "week") return num(item.cost_per_week) * durationOverride;
      if (rentalPeriod === "month") return num(item.cost_per_month) * durationOverride;
      return 0;
    };

    const baseCost = getRentalCost(eq, entry.custom_rate);
    let entryTotal = baseCost;
    const deliveryCharge =
      entry.custom_delivery_charge !== undefined && entry.custom_delivery_charge !== null
        ? entry.custom_delivery_charge
        : num(eq.pickup_delivery_cost);
    if (entry.include_delivery) entryTotal += deliveryCharge;

    const pricedLines = rows => rows.map(row => {
      // Zero-count legacy keys may point at removed records and are not rented.
      if (!row.inventory) return { ...row, cost: 0 };
      const cost = getRentalCost(row.inventory) * row.quantity;
      entryTotal += cost;
      return { ...row, cost };
    });
    const attachmentRows = pricedLines(bindings.attachmentRows);
    const subAttachmentRows = pricedLines(bindings.subAttachmentRows);
    return {
      ...context, pricedEntry: { ...entry, equipment_cost: entryTotal },
      baseCost, deliveryCost: entry.include_delivery ? deliveryCharge : 0,
      attachmentRows, subAttachmentRows, totalCost: entryTotal,
    };
  });
}

export function calcEquipment(selected, inventory = []) {
  return calcEquipmentPricing(selected, inventory).map(row => row.pricedEntry);
}

export function equipmentCostTotal(pricedEntries = []) {
  return pricedEntries.reduce((sum, entry) => sum + num(entry.equipment_cost), 0);
}

export function calcProject(project, inventory, settings = {}) {
  const items = (project.items || []).map((item) => ({ ...item, ...calcItem(item, project, inventory, settings) }));
  const equipment = calcEquipment(project.selected_equipment, inventory);
  const delivery = calcConcreteDelivery(
    { ...project, settings },
    (project.items || []).map((i) => ({
      ...i,
      excavation_method: i.excavation_method || project.excavation_method,
    })),
    inventory
  );
  const walls = calcWalls(project, inventory, settings);
  const poles = calcPoles(project.poles, inventory, settings);
  const wallCaps = calcWallCaps(project.wall_caps, inventory);

  const sum = (key) => items.reduce((s, i) => s + num(i[key]), 0);

  const itemsTotal = sum("item_total_cost") + delivery.concreteTotal;
  const wallTotal = walls.reduce((s, w) => s + num(w.calculatedCosts?.totalCost), 0);
  const polesTotal = poles.reduce((s, p) => s + num(p.total_cost), 0);
  const equipmentTotal = equipmentCostTotal(equipment);

  const totals = {
    // Bagged concrete is priced per item; ready-mix is priced per delivered truck.
    total_concrete_cost: sum("concrete_cost") + delivery.concreteTotal,
    concrete_delivery_cost: delivery.concreteTotal,
    concrete_delivered_yards: delivery.roundedYards,
    concrete_rate_per_yard: delivery.ratePerYard,
    concrete_trucks: delivery.trucksList,
    additional_stops_cost: delivery.additionalStopsCost,
    total_rebar_cost: sum("rebar_cost"),
    total_excavation_cost: sum("excavation_cost"),
    total_forming_materials_cost: sum("forming_cost"),
    total_labor_cost: sum("pouring_cost") + sum("finishing_cost"),
    total_pole_cost: poles.reduce((s, p) => s + num(p.pole_cost), 0),
    total_pole_painting_cost: poles.reduce((s, p) => s + num(p.pole_painting_cost), 0),
    total_brick_cost: walls.reduce((s, w) => s + num(w.calculatedCosts?.materialCost), 0),
    total_fill_cost: walls.reduce((s, w) => s + num(w.calculatedCosts?.internalMaterialCost), 0),
    total_equipment_cost: equipmentTotal,
    total_wall_cost: wallTotal,
    total_wall_cap_cost: wallCaps.total,
    wall_caps_by_material: wallCaps.byInventory,
    total_concrete_volume_cy: sum("concrete_volume_cy"),
    total_excavation_volume_cy: sum("excavation_volume_cy"),
    total_labor_hours: sum("finishing_hours") + sum("excavation_hours"),
  };

  totals.grand_total = itemsTotal + wallTotal + polesTotal + equipmentTotal + wallCaps.total;

  return {
    items, equipment, walls, poles, wallCaps: wallCaps.caps, totals, delivery,
    catalogIssues: foundationAssemblyCatalogIssues(project, inventory),
  };
}

export const money = (n) =>
  `$${num(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

import { useState, useEffect, useMemo, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";
